  const [authToken, setAuthToken] = useState<any>("");
  const [usrInfo, setUsrInfo] = useState<UserInfo>();

  useEffect(() => {
    if (localStorage.getItem("LogInSSCCTkn")) {
      setAuthToken(localStorage.getItem("LogInSSCCTkn"));
    }
  }, []);

  useEffect(() => {
    const getEvent = async () => {
      const endpoint = `${process.env.NEXT_PUBLIC_API_PATH}user/${params.usrId}`;
      const options = {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          authorization: authToken,
        },
      };

      try {
        const res: any = await fetch(endpoint, options);
        const uInfo: any = await res.json();
        if (res.status == 200) setUsrInfo(uInfo);
        else {
          showToast(uInfo, "error");
        }
      } catch (e) {
        showToast(e, "error");
      }
    };

    if (authToken) getEvent();
  }, [authToken, params.usrId]);

  const getImgPath = (img: string) => {
    return `${process.env.NEXT_PUBLIC_API_PATH}uploads/${img}`;
  };

